var json = pm.response.json();
var html = '';

if (json.entry && json.entry.length > 0) {
    var report = json.entry[0].resource;

    if (report.presentedForm && report.presentedForm.length > 0) {
        for (var i = 0; i < report.presentedForm.length; i++) {
            var attachment = report.presentedForm[i];

            if (attachment.contentType === 'text/html' && attachment.data) {
                // Decode base64 HTML
                html = atob(attachment.data);
                break;
            }

            if (attachment.contentType === 'text/html' && attachment.url) {
                html = '<p>HTML is at external URL: ' + attachment.url + '</p>';
                html += '<p>Use the "Fetch presentedForm by URL" request to retrieve it.</p>';
                break;
            }
        }
    }
}

if (!html) {
    html = '<div style="font-family:sans-serif;padding:20px;">',
    html += '<h2>No presentedForm HTML found</h2>';
    html += '<p>This DiagnosticReport does not contain an inline text/html presentedForm attachment.</p>';

    if (json.entry && json.entry[0] && json.entry[0].resource.presentedForm) {
        html += '<h3>Available presentedForm attachments:</h3><ul>';
        json.entry[0].resource.presentedForm.forEach(function(a) {
            html += '<li>contentType: ' + (a.contentType || 'N/A');
            html += ', has data: ' + (!!a.data) + ', url: ' + (a.url || 'N/A') + '</li>';
        });
        html += '</ul>';
    }
    html += '</div>';
}

// Wrap in a styled container
var template = `
  <div style='border:1px solid #ddd; border-radius:8px; padding:16px; margin:8px; background:#fff;'>
    <div style='font-family:sans-serif; font-size:12px; color:#666; margin-bottom:12px; padding-bottom:8px; border-bottom:1px solid #eee;'>
      FHIR DiagnosticReport – presentedForm HTML Preview
    </div>
    ${html}
  </div>
`;

pm.visualizer.set(template, { html: html });

